    37→/// A visual control descriptor (slider, button, toggle, etc.)
    38→class VisualControl {
    39→  static const String typeSlider = 'slider';
    40→  static const String typeButton = 'button';
    41→  static const String typeToggle = 'toggle';
    42→  static const String typeStepper = 'stepper';
    43→  static const String typeDropdown = 'dropdown';
    44→
    45→  final String id;
    46→  final String type;
    47→  final String label;
    48→  final String? stateKey; // which state key this control drives
    49→  final double? min;
    50→  final double? max;
    51→  final double? step;
    52→  final dynamic defaultValue;
    53→  final List<String>? options; // for dropdown
    54→  final String? action; // for button: 'play'|'pause'|'reset'|'step'|'check'|'randomize'
    55→  final String? unit; // e.g. 'K', 'atm', 'm³'
    56→
    57→  const VisualControl({
    58→    required this.id,
    59→    required this.type,
    60→    required this.label,
    61→    this.stateKey,
    62→    this.min,
    63→    this.max,
    64→    this.step,
    65→    this.defaultValue,
    66→    this.options,
    67→    this.action,
    68→    this.unit,
    69→  });
    70→
    71→  factory VisualControl.fromJson(Map<String, dynamic> json) {
    72→    return VisualControl(
    73→      id: json['id'] as String? ?? '',
    74→      type: json['type'] as String? ?? typeSlider,
    75→      label: json['label'] as String? ?? '',
    76→      stateKey: json['stateKey'] as String?,
    77→      min: (json['min'] as num?)?.toDouble(),
    78→      max: (json['max'] as num?)?.toDouble(),
    79→      step: (json['step'] as num?)?.toDouble(),
    80→      defaultValue: json['defaultValue'],
    81→      options: (json['options'] as List<dynamic>?)?.cast<String>(),
    82→      action: json['action'] as String?,
    83→      unit: json['unit'] as String?,
    84→    );
    85→  }
    86→
    87→  Map<String, dynamic> toJson() {
    88→    final m = <String, dynamic>{'id': id, 'type': type, 'label': label};
    89→    if (stateKey != null) m['stateKey'] = stateKey;
    90→    if (min != null) m['min'] = min;
    91→    if (max != null) m['max'] = max;
    92→    if (step != null) m['step'] = step;
    93→    if (defaultValue != null) m['defaultValue'] = defaultValue;
    94→    if (options != null) m['options'] = options;
    95→    if (action != null) m['action'] = action;
    96→    if (unit != null) m['unit'] = unit;
    97→    return m;
    98→  }
    99→}
