   221→/// Playback configuration
   222→class VisualPlayback {
   223→  final bool autoplay;
   224→  final bool allowStep;
   225→  final bool allowReset;
   226→  final int transitionMs;
   227→
   228→  const VisualPlayback({
   229→    this.autoplay = false,
