   234→
   235→  factory VisualPlayback.fromJson(Map<String, dynamic> json) {
   236→    return VisualPlayback(
   237→      autoplay: json['autoplay'] as bool? ?? false,
   238→      allowStep: json['allowStep'] as bool? ?? true,
   239→      allowReset: json['allowReset'] as bool? ?? true,
   240→      transitionMs: json['transitionMs'] as int? ?? 200,
   241→    );
   242→  }
   243→
   244→  Map<String, dynamic> toJson() => {
   245→    'autoplay': autoplay,
   246→    'allowStep': allowStep,
   247→    'allowReset': allowReset,
   248→    'transitionMs': transitionMs,
   249→  };
   250→
   251→  VisualPlayback copyWith({
   252→    bool? autoplay,
   253→    bool? allowStep,
   254→    bool? allowReset,
   255→    int? transitionMs,
   256→  }) => VisualPlayback(
   257→    autoplay: autoplay ?? this.autoplay,
   258→    allowStep: allowStep ?? this.allowStep,
   259→    allowReset: allowReset ?? this.allowReset,
   260→    transitionMs: transitionMs ?? this.transitionMs,
   261→  );
   262→}
