   264→/// The canonical content model for interactive-visual blocks.
   265→/// Replaces AnimationContent as the unified visual block.
   266→class InteractiveVisualContent implements BlockContent {
   267→  static const String engineVersion = 'sim-v1';
   268→  static const String templateGeneric = 'generic';
   269→  static const String templateIdealGasPiston = 'ideal-gas-piston';
   270→  static const String templateSortingBars = 'sorting-bars';
   271→  static const String templateVariableBindingMemory = 'variable-binding-memory';
   272→  static const String templateFunctionPlot = 'function-plot';
   273→  static const String templatePendulum = 'pendulum';
   274→  static const String templateWave = 'wave';
   275→  static const String templateProjectile = 'projectile';
   276→  static const String templatePythagorean = 'pythagorean';
   277→  static const String templateUnitCircle = 'unit-circle';
   278→  static const Set<String> knownTemplates = {
   279→    templateGeneric,
   280→    templateIdealGasPiston,
   281→    templateSortingBars,
   282→    templateVariableBindingMemory,
   283→    templateFunctionPlot,
   284→    templatePendulum,
   285→    templateWave,
