   308→  final List<Map<String, dynamic>> derivedState; // derived state rules
   309→
   310→  // Controls, formulas, checks
   311→  final List<VisualControl> controls;
   312→  final List<VisualFormula> formulas;
   313→  final List<VisualCheck> checks;
