   359→  factory InteractiveVisualContent.fromJson(Map<String, dynamic> json) {
   360→    final controlsRaw = json['controls'];
   361→    final formulasRaw = json['formulas'];
   362→    final checksRaw = json['checks'];
   363→    final derivedRaw = json['derivedState'];
   364→    final actionsRaw = json['actions'];
   365→    final generationMetaRaw = json['generationMeta'];
   366→
   367→    return InteractiveVisualContent(
   368→      version: json['version'] as String? ?? engineVersion,
   369→      mode: _normalizeMode(json['mode'] as String?),
   370→      template: json['template'] as String? ?? templateGeneric,
   371→      title: json['title'] as String? ?? '',
   372→      description: json['description'] as String?,
   373→      layoutPreset: _normalizeLayoutPreset(json['layoutPreset'] as String?),
   374→      controlsPosition: json['controlsPosition'] as String?,
