   491→      description: description ?? this.description,
   492→      layoutPreset: _normalizeLayoutPreset(layoutPreset ?? this.layoutPreset),
   493→      controlsPosition: controlsPosition ?? this.controlsPosition,
   494→      formulaPosition: formulaPosition ?? this.formulaPosition,
   495→      themeTone: _normalizeThemeTone(themeTone ?? this.themeTone),
   496→      accentColor: accentColor ?? this.accentColor,
   497→      initialState: initialState ?? this.initialState,
   498→      derivedState: derivedState ?? this.derivedState,
   499→      controls: controls ?? this.controls,
   500→      formulas: formulas ?? this.formulas,
   501→      checks: checks ?? this.checks,
   502→      scene: scene ?? this.scene,
   503→      bindings: bindings ?? this.bindings,
