   505→      playback: playback ?? this.playback,
   506→      aiPrompt: clearAiPrompt ? null : (aiPrompt ?? this.aiPrompt),
   507→      generationMeta: generationMeta ?? this.generationMeta,
   508→      legacyCustomHtml:
   509→          clearLegacyCustomHtml
   510→              ? null
   511→              : (legacyCustomHtml ?? this.legacyCustomHtml),
