   515→  /// Migrate legacy AnimationContent JSON to InteractiveVisualContent
   516→  static InteractiveVisualContent fromLegacyAnimationJson(
   517→    Map<String, dynamic> json,
   518→  ) {
   519→    final customHtml = json['customHtml'] as String?;
   520→    final aiPrompt = json['aiPrompt'] as String?;
   521→    return InteractiveVisualContent(
   522→      version: engineVersion,
   523→      mode: VisualMode.presentation,
   524→      template: templateGeneric,
   525→      title: '',
   526→      layoutPreset: VisualLayoutPreset.sceneOnly,
   527→      themeTone: VisualThemeTone.lightScience,
   528→      initialState: const {},
   529→      playback: const VisualPlayback(autoplay: true),
   530→      aiPrompt: aiPrompt,
   531→      legacyCustomHtml: customHtml,
   532→    );
   533→  }
   534→
   535→  static String _normalizeMode(String? mode) {
   536→    return VisualMode.all.contains(mode) ? mode! : VisualMode.presentation;
   537→  }
   538→
   539→  static String _normalizeLayoutPreset(String? preset) {
   540→    return VisualLayoutPreset.all.contains(preset)
   541→        ? preset!
   542→        : VisualLayoutPreset.split;
   543→  }
   544→
   545→  static String _normalizeThemeTone(String? tone) {
   546→    return VisualThemeTone.all.contains(tone)
   547→        ? tone!
   548→        : VisualThemeTone.lightScience;
   549→  }
   550→
   551→  static Map<String, dynamic>? _asStringDynamicMap(dynamic raw) {
   552→    if (raw is Map) return Map<String, dynamic>.from(raw);
   553→    return null;
