    36→const corsHeaders = {
    37→  'Access-Control-Allow-Origin': '*',
    38→  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
    39→};
    40→
    41→serve(async (req) => {
    42→  // Handle CORS preflight
    43→  if (req.method === 'OPTIONS') {
    44→    return new Response('ok', { headers: corsHeaders });
    45→  }
    46→
    47→  try {
