  2507→        _state['comparing'] = <int>[];
  2508→        _state['swapped'] = <int>[];
  2509→        _state['sorted'] = List.generate(n, (i) => i);
  2510→      });
  2511→      return;
  2512→    }
  2513→    final comparing = [idx, idx + 1];
  2514→    List<int> swapped = [];
  2515→    if (vals[idx] > vals[idx + 1]) {
  2516→      final tmp = vals[idx];
  2517→      vals[idx] = vals[idx + 1];
  2518→      vals[idx + 1] = tmp;
  2519→      swapped = [idx, idx + 1];
  2520→    }
  2521→    setState(() {
  2522→      _state['values'] = vals;
  2523→      _state['stepIndex'] = si + 1;
  2524→      _state['comparing'] = comparing;
  2525→      _state['swapped'] = swapped;
  2526→      _state['sorted'] = List.generate(pass, (i) => n - 1 - i);
  2527→    });
  2528→  }
  2529→
  2530→  void _stepVariableMemory() {
  2531→    final steps = (widget.spec['scene']?['steps'] as List?) ?? [];
  2532→    if (_stepIndex >= steps.length) return;
  2533→    final step = Map<String, dynamic>.from(steps[_stepIndex] as Map);
  2534→    final vars = List<Map>.from(_state['variables'] as List? ?? []);
