  2938→class _ViewerSortingBarsPainter extends CustomPainter {
  2939→  final List<int> values;
  2940→  final List<int> comparing;
  2941→  final List<int> swapped;
  2942→  final List<int> sorted;
  2943→  final bool isDark;
  2944→
  2945→  const _ViewerSortingBarsPainter({
  2946→    required this.values,
  2947→    required this.comparing,
  2948→    required this.swapped,
  2949→    required this.sorted,
  2950→    required this.isDark,
  2951→  });
  2952→
  2953→  @override
  2954→  void paint(Canvas canvas, Size size) {
  2955→    if (values.isEmpty) return;
  2956→    final n = values.length;
  2957→    final maxVal = values.reduce(math.max);
  2958→    final barWidth = (size.width - (n + 1) * 4.0) / n;
  2959→    final maxBarHeight = size.height - 30;
  2960→    for (int i = 0; i < n; i++) {
  2961→      final barH = (values[i] / maxVal) * maxBarHeight;
  2962→      final x = 4.0 + i * (barWidth + 4);
  2963→      final y = size.height - barH - 20;
  2964→      Color color;
  2965→      if (sorted.contains(i)) {
  2966→        color = const Color(0xFF3FB950);
  2967→      } else if (swapped.contains(i)) {
  2968→        color = const Color(0xFFFF7B72);
  2969→      } else if (comparing.contains(i)) {
  2970→        color = const Color(0xFFFFA657);
  2971→      } else {
  2972→        color =
  2973→            isDark ? const Color(0xFF388BFD) : const Color(0xFF0969DA);
  2974→      }
  2975→      canvas.drawRRect(
  2976→        RRect.fromRectAndRadius(
  2977→          Rect.fromLTWH(x, y, barWidth, barH),
  2978→          const Radius.circular(3),
  2979→        ),
  2980→        Paint()..color = color,
  2981→      );
  2982→      final tp =
  2983→          TextPainter(
  2984→            text: TextSpan(
  2985→              text: '${values[i]}',
  2986→              style: TextStyle(
  2987→                color:
  2988→                    isDark
  2989→                        ? const Color(0xFF8B949E)
  2990→                        : const Color(0xFF57606A),
  2991→                fontSize: 9,
  2992→              ),
  2993→            ),
  2994→            textDirection: TextDirection.ltr,
  2995→          )..layout();
  2996→      tp.paint(
  2997→        canvas,
  2998→        Offset(x + barWidth / 2 - tp.width / 2, size.height - 18),
  2999→      );
  3000→    }
  3001→  }
  3002→
  3003→  @override
  3004→  bool shouldRepaint(_ViewerSortingBarsPainter old) =>
  3005→      old.values != values || old.comparing != comparing;
  3006→}
