  });

  factory VisualTeaching.fromJson(Map<String, dynamic> json) {
    final highlightRaw = json['highlight'];
    final labelsRaw = json['labels'];
    final hintsRaw = json['hints'];
    return VisualTeaching(
      focus: json['focus'] as String?,
