    "confidence": <0.0-1.0>,
    "warnings": []
  }
}

TEMPLATE GUIDE — choose the templateFamily that best fits the concept:

- "generic": General visual scene with state display. Use when no specific template fits.
- "ideal-gas-piston": Physics — ideal gas law PV=nRT. runtime.mode="parametric". scene: {pistonHeightFraction, particleCount}. initialState: {P, V, n, T}.
- "sorting-bars": CS — sorting algorithm visualization. runtime.mode="static". scene: {algorithm: "bubble-sort", barCount: 9}. initialState: {values: [...], stepIndex: 0, comparing: [], swapped: [], sorted: []}.
- "variable-binding-memory": CS — variable to memory slot binding. runtime.mode="static". scene: {steps: [{code, varName, value, address}]}. initialState: {stepIndex: 0, variables: [], memory: []}.
- "function-plot": Math — plot a function with parameter sliders. runtime.mode="parametric". scene: {xMin, xMax, yMin, yMax, expression: "quadratic"}. initialState: {a, b, c}.
- "pendulum": Physics — simple pendulum. runtime.mode="simulation", autoplay=true. initialState: {length, gravity, angle0}.
- "wave": Physics — traveling sine wave. runtime.mode="simulation", autoplay=true. initialState: {amplitude, frequency, speed}.
- "projectile": Physics — projectile motion. runtime.mode="simulation", autoplay=false. initialState: {angle, velocity, gravity}.
