/// Runtime configuration for scene-v1 blocks
class VisualRuntime {
  static const String modeStatic = 'static';
  static const String modeParametric = 'parametric';
  static const String modeSimulation = 'simulation';
  static const Set<String> allModes = {modeStatic, modeParametric, modeSimulation};

  final String mode; // 'static' | 'parametric' | 'simulation'
  final double timeScale;
  final String solver; // 'euler' | 'rk4'
  final bool autoplay;

  const VisualRuntime({
    this.mode = modeStatic,
    this.timeScale = 1.0,
    this.solver = 'euler',
    this.autoplay = false,
  });

  factory VisualRuntime.fromJson(Map<String, dynamic> json) {
    final rawMode = json['mode'] as String? ?? modeStatic;
    return VisualRuntime(
      mode: allModes.contains(rawMode) ? rawMode : modeStatic,
      timeScale: (json['timeScale'] as num?)?.toDouble() ?? 1.0,
      solver: json['solver'] as String? ?? 'euler',
      autoplay: json['autoplay'] as bool? ?? false,
    );
  }

  Map<String, dynamic> toJson() => {
    'mode': mode,
    'timeScale': timeScale,
    'solver': solver,
    'autoplay': autoplay,
  };

  VisualRuntime copyWith({
    String? mode,
    double? timeScale,
    String? solver,
    bool? autoplay,
  }) => VisualRuntime(
    mode: mode ?? this.mode,
    timeScale: timeScale ?? this.timeScale,
    solver: solver ?? this.solver,
    autoplay: autoplay ?? this.autoplay,
  );
}

/// Teaching metadata for scene-v1 blocks
class VisualTeaching {
  final String? focus;
  final List<String> highlight;
  final Map<String, String> labels;
  final List<String> hints;

  const VisualTeaching({
    this.focus,
    this.highlight = const [],
    this.labels = const {},
    this.hints = const [],
  });

  factory VisualTeaching.fromJson(Map<String, dynamic> json) {
    final highlightRaw = json['highlight'];
    final labelsRaw = json['labels'];
    final hintsRaw = json['hints'];
    return VisualTeaching(
      focus: json['focus'] as String?,
      highlight: highlightRaw is List ? highlightRaw.cast<String>() : [],
      labels: labelsRaw is Map
          ? Map<String, String>.from(
              labelsRaw.map((k, v) => MapEntry(k.toString(), v.toString())),
            )
          : {},
      hints: hintsRaw is List ? hintsRaw.cast<String>() : [],
    );
  }

  Map<String, dynamic> toJson() {
    final m = <String, dynamic>{};
    if (focus != null) m['focus'] = focus;
    if (highlight.isNotEmpty) m['highlight'] = highlight;
    if (labels.isNotEmpty) m['labels'] = labels;
    if (hints.isNotEmpty) m['hints'] = hints;
    return m;
  }
}
