const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

interface SpecJson {
  version: string;
  templateFamily: string;
  runtime?: { mode: string; [key: string]: unknown };
  controls?: unknown[];
  [key: string]: unknown;
}

function validateSpec(obj: unknown): { valid: boolean; errors: string[] } {
  const errors: string[] = [];
  if (typeof obj !== 'object' || obj === null) {
    errors.push('Spec must be a JSON object');
    return { valid: false, errors };
  }
  const spec = obj as Record<string, unknown>;

  if (spec['version'] !== 'scene-v1') {
    errors.push(`version must be "scene-v1", got "${spec['version']}"`);
  }
  if (!spec['templateFamily'] || !KNOWN_TEMPLATES.includes(spec['templateFamily'] as string)) {
    errors.push(`templateFamily must be one of: ${KNOWN_TEMPLATES.join(', ')}. Got: "${spec['templateFamily']}"`);
  }
  const runtime = spec['runtime'] as Record<string, unknown> | undefined;
  if (!runtime || typeof runtime !== 'object') {
    errors.push('runtime object is required');
  } else {
    const validModes = ['static', 'parametric', 'simulation'];
    if (!validModes.includes(runtime['mode'] as string)) {
      errors.push(`runtime.mode must be one of: ${validModes.join(', ')}. Got: "${runtime['mode']}"`);
    }
  }
  if (spec['controls'] !== undefined && !Array.isArray(spec['controls'])) {
    errors.push('controls must be an array');
  }

  return { valid: errors.length === 0, errors };
}

function stripCodeFences(text: string): string {
  // Remove ```json ... ``` or ``` ... ``` wrappers
  const match = text.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (match) return match[1].trim();
  return text.trim();
}

async function callGemini(
  geminiUrl: string,
  messages: Array<{ role: string; parts: Array<{ text: string }> }>,
): Promise<string> {
  const body = {
    system_instruction: { parts: [{ text: SYSTEM_PROMPT }] },
    contents: messages,
    generationConfig: {
      temperature: 0.4,
      maxOutputTokens: MAX_OUTPUT_TOKENS,
    },
  };
  const res = await fetch(geminiUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
  if (!res.ok) {
    const errText = await res.text();
    throw new Error(`Gemini API error ${res.status}: ${errText}`);
  }
  const data = await res.json();
  return data?.candidates?.[0]?.content?.parts?.[0]?.text ?? '';
}

serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    const { prompt } = await req.json();
    if (!prompt || typeof prompt !== 'string' || prompt.trim().length === 0) {
      return new Response(
        JSON.stringify({ error: 'prompt is required' }),
        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
      );
    }

    const geminiApiKey = Deno.env.get('GEMINI_API_KEY');
    if (!geminiApiKey) {
      return new Response(
        JSON.stringify({ error: 'Platform AI service not configured' }),
        { status: 503, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
      );
    }

    const geminiUrl = `${GEMINI_BASE_URL}/models/${MODEL}:generateContent?key=${geminiApiKey}`;
    const messages: Array<{ role: string; parts: Array<{ text: string }> }> = [
      { role: 'user', parts: [{ text: prompt.trim() }] },
    ];

    // First attempt
    let rawText = await callGemini(geminiUrl, messages);
    if (!rawText.trim()) {
      return new Response(
        JSON.stringify({ error: 'AI returned empty response' }),
        { status: 502, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
      );
    }

    let specObj: unknown;
    try {
      specObj = JSON.parse(stripCodeFences(rawText));
    } catch {
      specObj = null;
    }

    let validation = validateSpec(specObj);

    // Repair loop: one retry on validation failure
    if (!validation.valid) {
      console.warn('[gemini-generate] Validation failed, attempting repair:', validation.errors);
      const repairPrompt = `Your previous response had validation errors:\n${validation.errors.join('\n')}\n\nPrevious response:\n${rawText}\n\nPlease fix the issues and return a valid JSON spec that passes all validation rules. Return ONLY the JSON object.`;
      messages.push({ role: 'model', parts: [{ text: rawText }] });
      messages.push({ role: 'user', parts: [{ text: repairPrompt }] });

      rawText = await callGemini(geminiUrl, messages);
      try {
        specObj = JSON.parse(stripCodeFences(rawText));
      } catch {
        specObj = null;
      }
      validation = validateSpec(specObj);
    }

    if (!validation.valid) {
      console.error('[gemini-generate] Spec still invalid after repair:', validation.errors);
      return new Response(
        JSON.stringify({
          error: `Generated spec failed validation: ${validation.errors.join('; ')}`,
          rawText,
        }),
        { status: 422, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
      );
    }

    return new Response(
      JSON.stringify({ spec: specObj as SpecJson }),
      { status: 200, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    );
  } catch (err) {
    console.error('[gemini-generate] Unexpected error:', err);
    return new Response(
      JSON.stringify({ error: String(err) }),
      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    );
  }
});
