import 'package:flutter/material.dart';
import '../visual_template_renderer.dart';

class IdealGasPistonRenderer extends VisualTemplateRenderer {
  static const double _gasConstant = 0.08206; // L·atm/(mol·K)

  const IdealGasPistonRenderer({
    required super.state,
    required super.scene,
    required super.isDark,
    super.repaint,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final P = (state['P'] as num?)?.toDouble() ?? 1.0;
    final n = (state['n'] as num?)?.toDouble() ?? 1.0;
    final T = (state['T'] as num?)?.toDouble() ?? 273.0;

    // Derived: V = nRT/P
    final V = (n * _gasConstant * T / P).clamp(1.0, 80.0);
    final maxV = n * _gasConstant * 600 / 0.1; // max volume at extreme conditions
    final minV = n * _gasConstant * 100 / 10.0;
    final vFraction = ((V - minV) / (maxV - minV)).clamp(0.1, 0.9);

    final cylLeft = size.width * 0.25;
    final cylRight = size.width * 0.75;
    final cylWidth = cylRight - cylLeft;
    final cylTop = size.height * 0.1;
    final cylBottom = size.height * 0.85;
    final cylHeight = cylBottom - cylTop;

    // Cylinder walls
    final wallPaint = Paint()
      ..color = isDark ? const Color(0xFF30363D) : const Color(0xFFB0BEC5)
      ..strokeWidth = 3.0
      ..style = PaintingStyle.stroke;

    // Left wall
    canvas.drawLine(Offset(cylLeft, cylTop), Offset(cylLeft, cylBottom), wallPaint);
    // Right wall
    canvas.drawLine(Offset(cylRight, cylTop), Offset(cylRight, cylBottom), wallPaint);
    // Bottom
    canvas.drawLine(Offset(cylLeft, cylBottom), Offset(cylRight, cylBottom), wallPaint);

    // Piston
    final pistonY = cylBottom - vFraction * cylHeight;
    final pistonPaint = Paint()
      ..color = isDark ? const Color(0xFF484F58) : const Color(0xFF78909C)
      ..style = PaintingStyle.fill;
    canvas.drawRect(
      Rect.fromLTWH(cylLeft, pistonY - 8, cylWidth, 8),
      pistonPaint,
    );
    canvas.drawRect(
      Rect.fromLTWH(cylLeft, pistonY - 8, cylWidth, 8),
      Paint()
        ..color = isDark ? const Color(0xFF30363D) : const Color(0xFF90A4AE)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 1.0,
    );

    // Gas region (filled)
    final gasPaint = Paint()
      ..color = primaryColor.withOpacity(0.15)
      ..style = PaintingStyle.fill;
    canvas.drawRect(
      Rect.fromLTWH(cylLeft, pistonY, cylWidth, cylBottom - pistonY),
      gasPaint,
    );

    // Labels
    _drawStateLabel(canvas, size, P, V, n, T);
  }

  void _drawStateLabel(Canvas canvas, Size size, double P, double V, double n, double T) {
    final V_derived = (n * _gasConstant * T / P);
    final labels = [
      'P = ${P.toStringAsFixed(1)} atm',
      'V = ${V_derived.toStringAsFixed(1)} L',
      'T = ${T.toStringAsFixed(0)} K',
      'n = ${n.toStringAsFixed(1)} mol',
    ];
    double y = 8;
    for (final label in labels) {
      final tp = TextPainter(
        text: TextSpan(
          text: label,
          style: TextStyle(color: textColor, fontSize: 10, fontWeight: FontWeight.w500),
        ),
        textDirection: TextDirection.ltr,
      )..layout();
      tp.paint(canvas, Offset(8, y));
      y += 14;
    }
  }

  @override
  bool shouldRepaint(IdealGasPistonRenderer old) =>
      old.state['P'] != state['P'] ||
      old.state['n'] != state['n'] ||
      old.state['T'] != state['T'];
}
