    42→      if (html == null || html.trim().isEmpty) {
    43→        final error = data?['error'] as String? ?? 'AI returned empty response';
    44→        return VisualGenerationResult(error: error);
    45→      }
    46→
    47→      final spec = InteractiveVisualContent.fromLegacyAnimationJson({
    48→        'customHtml': html,
    49→        'aiPrompt': prompt,
    50→      });
    51→
    52→      return VisualGenerationResult(spec: spec);
    53→    } on FunctionException catch (e) {
    54→      return VisualGenerationResult(
    55→        error: e.details?.toString() ?? 'Edge Function error: ${e.reasonPhrase}',
    56→      );
    57→    } catch (e) {
    58→      return VisualGenerationResult(error: e.toString());
    59→    }
    60→  }
