import 'package:flutter/material.dart';
import 'package:flutter/scheduler.dart';

enum RuntimeLifecycle { idle, ready, running, paused, disposed }

/// Controls the lifecycle and state of an interactive visual scene.
/// Handles static (step-driven), parametric (param-reactive), and
/// simulation (Ticker-based) runtime modes.
class RuntimeController extends ChangeNotifier {
  final String mode; // 'static' | 'parametric' | 'simulation'
  final Map<String, dynamic> initialState;

  Map<String, dynamic> _state;
  RuntimeLifecycle _lifecycle = RuntimeLifecycle.idle;
  Ticker? _ticker;
  Duration _lastTick = Duration.zero;
  bool _tickerAttached = false;

  /// Called each simulation tick with current state and delta time (seconds).
  void Function(Map<String, dynamic> state, double dt)? simulationStep;

  RuntimeController({
    required this.mode,
    required this.initialState,
  }) : _state = Map<String, dynamic>.from(initialState);

  Map<String, dynamic> get state => Map<String, dynamic>.from(_state);
  RuntimeLifecycle get lifecycle => _lifecycle;
  bool get isRunning => _lifecycle == RuntimeLifecycle.running;
  bool get isPaused => _lifecycle == RuntimeLifecycle.paused;
  bool get isReady => _lifecycle == RuntimeLifecycle.ready;

  void attach(TickerProvider vsync) {
    if (_tickerAttached || _lifecycle == RuntimeLifecycle.disposed) return;
    if (mode == 'simulation') {
      _ticker = vsync.createTicker(_onTick);
      _tickerAttached = true;
    }
    _lifecycle = RuntimeLifecycle.ready;
    notifyListeners();
  }

  void ready() {
    if (_lifecycle == RuntimeLifecycle.idle) {
      _lifecycle = RuntimeLifecycle.ready;
      notifyListeners();
    }
  }

  void play() {
    if (_lifecycle == RuntimeLifecycle.disposed) return;
    if (mode == 'simulation' && _ticker != null && !_ticker!.isActive) {
      _lastTick = Duration.zero;
      _ticker!.start();
    }
    _lifecycle = RuntimeLifecycle.running;
    notifyListeners();
  }

  void pause() {
    if (_lifecycle != RuntimeLifecycle.running) return;
    if (mode == 'simulation') _ticker?.stop();
    _lifecycle = RuntimeLifecycle.paused;
    notifyListeners();
  }

  void reset() {
    if (_lifecycle == RuntimeLifecycle.disposed) return;
    if (mode == 'simulation') {
      _ticker?.stop();
      _lastTick = Duration.zero;
    }
    _state = Map<String, dynamic>.from(initialState);
    _lifecycle = RuntimeLifecycle.ready;
    notifyListeners();
  }

  /// Step forward (for static mode)
  void step(void Function(Map<String, dynamic>) stepFn) {
    if (_lifecycle == RuntimeLifecycle.disposed) return;
    stepFn(_state);
    notifyListeners();
  }

  /// Update a parameter value (for parametric/slider controls)
  void updateParam(String key, dynamic value) {
    if (_lifecycle == RuntimeLifecycle.disposed) return;
    _state[key] = value;
    notifyListeners();
  }

  void _onTick(Duration elapsed) {
    if (_lifecycle != RuntimeLifecycle.running) return;
    if (_lastTick == Duration.zero) {
      _lastTick = elapsed;
      return;
    }
    final dt = (elapsed - _lastTick).inMicroseconds / 1000000.0;
    _lastTick = elapsed;
    if (dt <= 0 || dt > 0.1) return; // skip bad frames
    simulationStep?.call(_state, dt);
    notifyListeners();
  }

  @override
  void dispose() {
    _lifecycle = RuntimeLifecycle.disposed;
    _ticker?.stop();
    _ticker?.dispose();
    _ticker = null;
    super.dispose();
  }
}

import 'package:flutter/material.dart';

/// Base class for all template-specific CustomPainters.
abstract class VisualTemplateRenderer extends CustomPainter {
  final Map<String, dynamic> state;
  final Map<String, dynamic> scene;
  final bool isDark;

  const VisualTemplateRenderer({
    required this.state,
    required this.scene,
    required this.isDark,
    Listenable? repaint,
  }) : super(repaint: repaint);

  Color get axisColor => isDark ? const Color(0xFF484F58) : const Color(0xFFB0BEC5);
  Color get primaryColor => isDark ? const Color(0xFF58A6FF) : const Color(0xFF0969DA);
  Color get accentColor => isDark ? const Color(0xFFFFA657) : const Color(0xFFE36209);
  Color get successColor => const Color(0xFF3FB950);
  Color get errorColor => const Color(0xFFFF7B72);
  Color get textColor => isDark ? const Color(0xFFE6EDF3) : const Color(0xFF1F2328);
  Color get labelColor => isDark ? const Color(0xFF8B949E) : const Color(0xFF57606A);
  Color get bgColor => isDark ? const Color(0xFF0D1117) : const Color(0xFFF0F6FF);
}

import 'dart:math' as math;
import 'package:flutter/material.dart';
import '../visual_template_renderer.dart';

class SortingBarsRenderer extends VisualTemplateRenderer {
  const SortingBarsRenderer({
    required super.state,
    required super.scene,
    required super.isDark,
    super.repaint,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final values = (state['values'] as List?)?.cast<int>() ?? [5, 3, 8, 1, 9, 2, 7, 4, 6];
    final comparing = (state['comparing'] as List?)?.cast<int>() ?? [];
    final swapped = (state['swapped'] as List?)?.cast<int>() ?? [];
    final sorted = (state['sorted'] as List?)?.cast<int>() ?? [];
    if (values.isEmpty) return;
    final n = values.length;
    final maxVal = values.reduce(math.max);
    final barWidth = (size.width - (n + 1) * 4.0) / n;
    final maxBarHeight = size.height - 30;
    for (int i = 0; i < n; i++) {
      final barH = (values[i] / maxVal) * maxBarHeight;
      final x = 4.0 + i * (barWidth + 4);
      final y = size.height - barH - 20;
      Color color;
      if (sorted.contains(i)) {
        color = successColor;
      } else if (swapped.contains(i)) {
        color = errorColor;
      } else if (comparing.contains(i)) {
        color = accentColor;
      } else {
        color = primaryColor;
      }
      canvas.drawRRect(
        RRect.fromRectAndRadius(
          Rect.fromLTWH(x, y, barWidth, barH),
          const Radius.circular(3),
        ),
        Paint()..color = color,
      );
      final tp = TextPainter(
        text: TextSpan(
          text: '${values[i]}',
          style: TextStyle(color: labelColor, fontSize: 9),
        ),
        textDirection: TextDirection.ltr,
      )..layout();
      tp.paint(canvas, Offset(x + barWidth / 2 - tp.width / 2, size.height - 18));
    }
  }

  @override
  bool shouldRepaint(SortingBarsRenderer old) =>
      old.state['values'] != state['values'] ||
      old.state['comparing'] != state['comparing'] ||
      old.state['swapped'] != state['swapped'] ||
      old.state['sorted'] != state['sorted'];

  /// Perform one bubble sort step, mutating [state].
  static void performStep(Map<String, dynamic> state) {
    final vals = List<int>.from(state['values'] as List? ?? []);
    final n = vals.length;
    int si = state['stepIndex'] as int? ?? 0;
    final stepsPerPass = n - 1;
    final pass = si ~/ stepsPerPass;
    final idx = si % stepsPerPass;
    if (pass >= n - 1) {
      state['comparing'] = <int>[];
      state['swapped'] = <int>[];
      state['sorted'] = List.generate(n, (i) => i);
      return;
    }
    final comparing = [idx, idx + 1];
    List<int> swapped = [];
    if (vals[idx] > vals[idx + 1]) {
      final tmp = vals[idx];
      vals[idx] = vals[idx + 1];
      vals[idx + 1] = tmp;
      swapped = [idx, idx + 1];
    }
    state['values'] = vals;
    state['stepIndex'] = si + 1;
    state['comparing'] = comparing;
    state['swapped'] = swapped;
    state['sorted'] = List.generate(pass, (i) => n - 1 - i);
  }
}

import 'dart:math' as math;
import 'package:flutter/material.dart';
import '../visual_template_renderer.dart';

class FunctionPlotRenderer extends VisualTemplateRenderer {
  const FunctionPlotRenderer({
    required super.state,
    required super.scene,
    required super.isDark,
    super.repaint,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final a = (state['a'] as num?)?.toDouble() ?? 1.0;
    final b = (state['b'] as num?)?.toDouble() ?? 0.0;
    final c = (state['c'] as num?)?.toDouble() ?? 0.0;
    final xMin = (scene['xMin'] as num?)?.toDouble() ?? -10.0;
    final xMax = (scene['xMax'] as num?)?.toDouble() ?? 10.0;
    final yMin = (scene['yMin'] as num?)?.toDouble() ?? -20.0;
    final yMax = (scene['yMax'] as num?)?.toDouble() ?? 20.0;

    final xRange = xMax - xMin;
    final yRange = yMax - yMin;

    double toCanvasX(double x) => (x - xMin) / xRange * size.width;
    double toCanvasY(double y) => size.height - (y - yMin) / yRange * size.height;

    // Draw axes
    final axisPaint = Paint()..color = axisColor..strokeWidth = 1.0;
    // X axis
    final yAxisPos = toCanvasY(0).clamp(0.0, size.height);
    canvas.drawLine(Offset(0, yAxisPos), Offset(size.width, yAxisPos), axisPaint);
    // Y axis
    final xAxisPos = toCanvasX(0).clamp(0.0, size.width);
    canvas.drawLine(Offset(xAxisPos, 0), Offset(xAxisPos, size.height), axisPaint);

    // Draw axis labels
    _drawAxisLabel(canvas, '0', Offset(xAxisPos + 4, yAxisPos + 4));
    _drawAxisLabel(canvas, 'x', Offset(size.width - 12, yAxisPos - 14));
    _drawAxisLabel(canvas, 'y', Offset(xAxisPos + 4, 4));

    // Draw curve (300 points)
    final curvePaint = Paint()
      ..color = primaryColor
      ..strokeWidth = 2.0
      ..style = PaintingStyle.stroke
      ..strokeCap = StrokeCap.round;

    final path = Path();
    bool firstPoint = true;
    const sampleCount = 300;
    for (int i = 0; i <= sampleCount; i++) {
      final x = xMin + (i / sampleCount) * xRange;
      final y = a * x * x + b * x + c; // quadratic f(x) = ax² + bx + c
      final cx = toCanvasX(x);
      final cy = toCanvasY(y);
      if (cy.isNaN || cy.isInfinite) {
        firstPoint = true;
        continue;
      }
      if (firstPoint) {
        path.moveTo(cx, cy);
        firstPoint = false;
      } else {
        path.lineTo(cx, cy);
      }
    }
    canvas.drawPath(path, curvePaint);

    // Draw vertex point
    if (a.abs() > 0.001) {
      final vx = -b / (2 * a);
      final vy = a * vx * vx + b * vx + c;
      if (vx >= xMin && vx <= xMax && vy >= yMin && vy <= yMax) {
        canvas.drawCircle(
          Offset(toCanvasX(vx), toCanvasY(vy)),
          4,
          Paint()..color = accentColor,
        );
      }
    }
  }

  void _drawAxisLabel(Canvas canvas, String text, Offset offset) {
    final tp = TextPainter(
      text: TextSpan(text: text, style: TextStyle(color: labelColor, fontSize: 9)),
      textDirection: TextDirection.ltr,
    )..layout();
    tp.paint(canvas, offset);
  }

  @override
  bool shouldRepaint(FunctionPlotRenderer old) =>
      old.state['a'] != state['a'] ||
      old.state['b'] != state['b'] ||
      old.state['c'] != state['c'];
}

import 'dart:math' as math;
import 'package:flutter/material.dart';
import '../visual_template_renderer.dart';

class UnitCircleRenderer extends VisualTemplateRenderer {
  const UnitCircleRenderer({
    required super.state,
    required super.scene,
    required super.isDark,
    super.repaint,
  });

  /// Simulation step: increment angle
  static void simulationStep(Map<String, dynamic> state, double dt) {
    final angle = (state['angle'] as num?)?.toDouble() ?? 0.0;
    state['angle'] = (angle + dt * 60) % 360;
  }

  @override
  void paint(Canvas canvas, Size size) {
    final angleDeg = (state['angle'] as num?)?.toDouble() ?? 45.0;
    final angleRad = angleDeg * math.pi / 180;
    final cosVal = math.cos(angleRad);
    final sinVal = math.sin(angleRad);

    final cx = size.width / 2;
    final cy = size.height / 2;
    final radius = math.min(cx, cy) * 0.75;

    // Draw axes
    final axisPaint = Paint()..color = axisColor..strokeWidth = 1.0;
    canvas.drawLine(Offset(cx - radius - 15, cy), Offset(cx + radius + 15, cy), axisPaint);
    canvas.drawLine(Offset(cx, cy - radius - 15), Offset(cx, cy + radius + 15), axisPaint);

    // Draw unit circle
    final circlePaint = Paint()
      ..color = axisColor
      ..strokeWidth = 1.5
      ..style = PaintingStyle.stroke;
    canvas.drawCircle(Offset(cx, cy), radius, circlePaint);

    // Draw radius line
    final px = cx + cosVal * radius;
    final py = cy - sinVal * radius; // y flipped
    final radiusPaint = Paint()..color = primaryColor..strokeWidth = 2.0;
    canvas.drawLine(Offset(cx, cy), Offset(px, py), radiusPaint);

    // Point on circle
    canvas.drawCircle(Offset(px, py), 5, Paint()..color = primaryColor);

    // cos projection (horizontal)
    final cosPaint = Paint()..color = accentColor..strokeWidth = 1.5..style = PaintingStyle.stroke;
    final cosPath = Path()
      ..moveTo(px, py)
      ..lineTo(px, cy);
    canvas.drawPath(cosPath, cosPaint..strokeWidth = 1.5);
    canvas.drawLine(Offset(cx, cy), Offset(px, cy), Paint()..color = accentColor..strokeWidth = 2.0);

    // sin projection (vertical)
    final sinPaint = Paint()..color = successColor..strokeWidth = 2.0;
    canvas.drawLine(Offset(cx, cy), Offset(cx, py), sinPaint);

    // Labels
    _drawLabel(canvas, 'cos θ = ${cosVal.toStringAsFixed(2)}', Offset(4, size.height - 32), accentColor);
    _drawLabel(canvas, 'sin θ = ${sinVal.toStringAsFixed(2)}', Offset(4, size.height - 18), successColor);
    _drawLabel(canvas, '${angleDeg.toStringAsFixed(0)}°', Offset(cx + 8, cy + 8), textColor);
  }

  void _drawLabel(Canvas canvas, String text, Offset offset, Color color) {
    final tp = TextPainter(
      text: TextSpan(
          text: text,
          style: TextStyle(
              color: color, fontSize: 10, fontWeight: FontWeight.w600)),
      textDirection: TextDirection.ltr,
    )..layout();
    tp.paint(canvas, offset);
  }

  @override
  bool shouldRepaint(UnitCircleRenderer old) =>
      old.state['angle'] != state['angle'];
}

import 'package:flutter/material.dart';
import '../visual_template_renderer.dart';

class IdealGasPistonRenderer extends VisualTemplateRenderer {
  static const double _gasConstant = 0.08206; // L·atm/(mol·K)

  const IdealGasPistonRenderer({
    required super.state,
    required super.scene,
    required super.isDark,
    super.repaint,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final P = (state['P'] as num?)?.toDouble() ?? 1.0;
    final n = (state['n'] as num?)?.toDouble() ?? 1.0;
    final T = (state['T'] as num?)?.toDouble() ?? 273.0;

    // Derived: V = nRT/P
    final vDerived = (n * _gasConstant * T / P).clamp(1.0, 80.0);
    final maxV = n * _gasConstant * 600 / 0.1; // max volume at extreme conditions
    final minV = n * _gasConstant * 100 / 10.0;
    final vFraction = ((vDerived - minV) / (maxV - minV)).clamp(0.1, 0.9);

    final cylLeft = size.width * 0.25;
    final cylRight = size.width * 0.75;
    final cylWidth = cylRight - cylLeft;
    final cylTop = size.height * 0.1;
    final cylBottom = size.height * 0.85;
    final cylHeight = cylBottom - cylTop;

    // Cylinder walls
    final wallPaint = Paint()
      ..color = isDark ? const Color(0xFF30363D) : const Color(0xFFB0BEC5)
      ..strokeWidth = 3.0
      ..style = PaintingStyle.stroke;

    // Left wall
    canvas.drawLine(Offset(cylLeft, cylTop), Offset(cylLeft, cylBottom), wallPaint);
    // Right wall
    canvas.drawLine(Offset(cylRight, cylTop), Offset(cylRight, cylBottom), wallPaint);
    // Bottom
    canvas.drawLine(Offset(cylLeft, cylBottom), Offset(cylRight, cylBottom), wallPaint);

    // Piston
    final pistonY = cylBottom - vFraction * cylHeight;
    final pistonPaint = Paint()
      ..color = isDark ? const Color(0xFF484F58) : const Color(0xFF78909C)
      ..style = PaintingStyle.fill;
    canvas.drawRect(
      Rect.fromLTWH(cylLeft, pistonY - 8, cylWidth, 8),
      pistonPaint,
    );
    canvas.drawRect(
      Rect.fromLTWH(cylLeft, pistonY - 8, cylWidth, 8),
      Paint()
        ..color = isDark ? const Color(0xFF30363D) : const Color(0xFF90A4AE)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 1.0,
    );

    // Gas region (filled)
    final gasPaint = Paint()
      ..color = primaryColor.withOpacity(0.15)
      ..style = PaintingStyle.fill;
    canvas.drawRect(
      Rect.fromLTWH(cylLeft, pistonY, cylWidth, cylBottom - pistonY),
      gasPaint,
    );

    // Labels
    _drawStateLabel(canvas, P, n, T);
  }

  void _drawStateLabel(Canvas canvas, double P, double n, double T) {
    final vDerived = n * _gasConstant * T / P;
    final labels = [
      'P = ${P.toStringAsFixed(1)} atm',
      'V = ${vDerived.toStringAsFixed(1)} L',
      'T = ${T.toStringAsFixed(0)} K',
      'n = ${n.toStringAsFixed(1)} mol',
    ];
    double y = 8;
    for (final label in labels) {
      final tp = TextPainter(
        text: TextSpan(
          text: label,
          style: TextStyle(
              color: textColor, fontSize: 10, fontWeight: FontWeight.w500),
        ),
        textDirection: TextDirection.ltr,
      )..layout();
      tp.paint(canvas, Offset(8, y));
      y += 14;
    }
  }

  @override
  bool shouldRepaint(IdealGasPistonRenderer old) =>
      old.state['P'] != state['P'] ||
      old.state['n'] != state['n'] ||
      old.state['T'] != state['T'];
}

import 'dart:math' as math;
import 'package:flutter/material.dart';
import '../visual_template_renderer.dart';

class ProjectileRenderer extends VisualTemplateRenderer {
  const ProjectileRenderer({
    required super.state,
    required super.scene,
    required super.isDark,
    super.repaint,
  });

  /// Euler integration step for projectile motion
  static void simulationStep(Map<String, dynamic> state, double dt) {
    final double x = (state['_x'] as num?)?.toDouble() ?? 0.0;
    final double y = (state['_y'] as num?)?.toDouble() ?? 0.0;
    final double vx = (state['_vx'] as num?)?.toDouble() ?? 0.0;
    double vy = (state['_vy'] as num?)?.toDouble() ?? 0.0;
    final double g = (state['gravity'] as num?)?.toDouble() ?? 9.8;

    if (y <= 0 && (state['_launched'] as bool? ?? false) && vy < 0) {
      // Hit the ground
      state['_launched'] = false;
      return;
    }

    vy -= g * dt;
    final nx = x + vx * dt;
    final ny = y + vy * dt;

    final trail = List<Map<String, double>>.from(
      (state['_trail'] as List?)
              ?.map((e) => Map<String, double>.from(e as Map)) ??
          [],
    );
    if (state['_launched'] as bool? ?? false) {
      trail.add({'x': x, 'y': y});
      if (trail.length > 200) trail.removeAt(0);
    }

    state['_x'] = nx;
    state['_y'] = ny < 0 ? 0.0 : ny;
    state['_vx'] = vx;
    state['_vy'] = ny < 0 ? 0.0 : vy;
    state['_trail'] = trail;
  }

  /// Launch the projectile based on angle and velocity
  static void launch(Map<String, dynamic> state) {
    final angle = (state['angle'] as num?)?.toDouble() ?? 45.0;
    final v0 = (state['velocity'] as num?)?.toDouble() ?? 20.0;
    final rad = angle * math.pi / 180;
    state['_x'] = 0.0;
    state['_y'] = 0.0;
    state['_vx'] = v0 * math.cos(rad);
    state['_vy'] = v0 * math.sin(rad);
    state['_trail'] = <Map<String, double>>[];
    state['_launched'] = true;
  }

  @override
  void paint(Canvas canvas, Size size) {
    final angle = (state['angle'] as num?)?.toDouble() ?? 45.0;
    final v0 = (state['velocity'] as num?)?.toDouble() ?? 20.0;
    final g = (state['gravity'] as num?)?.toDouble() ?? 9.8;
    final launched = state['_launched'] as bool? ?? false;

    // Calculate trajectory range for scaling
    final rad = angle * math.pi / 180;
    final totalTime = 2 * v0 * math.sin(rad) / g;
    final maxRange = v0 * math.cos(rad) * totalTime;
    final maxHeight = math.pow(v0 * math.sin(rad), 2) / (2 * g);
    final scaleX = maxRange > 0 ? (size.width * 0.9) / maxRange : 1.0;
    final scaleY = maxHeight > 0 ? (size.height * 0.8) / maxHeight : 1.0;

    double toCanvasX(double wx) => size.width * 0.05 + wx * scaleX;
    double toCanvasY(double wy) => size.height * 0.9 - wy * scaleY;

    // Draw ground
    canvas.drawLine(
      Offset(0, toCanvasY(0)),
      Offset(size.width, toCanvasY(0)),
      Paint()
        ..color = axisColor
        ..strokeWidth = 1.5,
    );

    // Draw predicted trajectory (dashed)
    if (!launched) {
      final dashPaint = Paint()
        ..color = axisColor.withOpacity(0.5)
        ..strokeWidth = 1.0
        ..style = PaintingStyle.stroke;
      final path = Path();
      bool first = true;
      for (int i = 0; i <= 100; i++) {
        final t = (i / 100) * totalTime;
        final wx = v0 * math.cos(rad) * t;
        final wy = v0 * math.sin(rad) * t - 0.5 * g * t * t;
        if (wy < 0) break;
        final cx = toCanvasX(wx);
        final cy = toCanvasY(wy);
        if (first) {
          path.moveTo(cx, cy);
          first = false;
        } else {
          path.lineTo(cx, cy);
        }
      }
      canvas.drawPath(path, dashPaint);
    }

    // Draw trail
    final trail = (state['_trail'] as List?)
            ?.map((e) => Map<String, double>.from(e as Map))
            .toList() ??
        [];
    if (trail.length > 1) {
      final trailPaint = Paint()
        ..color = primaryColor.withOpacity(0.5)
        ..strokeWidth = 2.0
        ..style = PaintingStyle.stroke;
      final path = Path();
      path.moveTo(toCanvasX(trail.first['x']!), toCanvasY(trail.first['y']!));
      for (final pt in trail.skip(1)) {
        path.lineTo(toCanvasX(pt['x']!), toCanvasY(pt['y']!));
      }
      canvas.drawPath(path, trailPaint);
    }

    // Draw current ball
    final curX = (state['_x'] as num?)?.toDouble() ?? 0.0;
    final curY = (state['_y'] as num?)?.toDouble() ?? 0.0;
    canvas.drawCircle(
      Offset(toCanvasX(curX), toCanvasY(curY)),
      6,
      Paint()..color = accentColor,
    );

    // Info label
    final infoText = launched
        ? 'x=${curX.toStringAsFixed(1)}m  y=${curY.toStringAsFixed(1)}m'
        : '${angle.toStringAsFixed(0)}° @ ${v0.toStringAsFixed(0)} m/s';
    final tp = TextPainter(
      text:
          TextSpan(text: infoText, style: TextStyle(color: labelColor, fontSize: 10)),
      textDirection: TextDirection.ltr,
    )..layout();
    tp.paint(canvas, const Offset(8, 8));
  }

  @override
  bool shouldRepaint(ProjectileRenderer old) =>
      old.state['_x'] != state['_x'] ||
      old.state['_y'] != state['_y'] ||
      old.state['angle'] != state['angle'] ||
      old.state['velocity'] != state['velocity'] ||
      old.state['_launched'] != state['_launched'];
}

import 'package:flutter/material.dart';
import 'visual_template_renderer.dart';
import 'renderers/sorting_bars_renderer.dart';
import 'renderers/function_plot_renderer.dart';
import 'renderers/unit_circle_renderer.dart';
import 'renderers/ideal_gas_piston_renderer.dart';
import 'renderers/projectile_renderer.dart';

class VisualRendererFactory {
  VisualRendererFactory._();

  static CustomPainter? create({
    required String templateFamily,
    required Map<String, dynamic> state,
    required Map<String, dynamic> scene,
    required bool isDark,
    Listenable? repaint,
  }) {
    switch (templateFamily) {
      case 'sorting-bars':
        return SortingBarsRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'function-plot':
        return FunctionPlotRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'unit-circle':
        return UnitCircleRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'ideal-gas-piston':
        return IdealGasPistonRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'projectile':
        return ProjectileRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      default:
        return null;
    }
  }

  /// Returns the simulation step function for a template, or null if not a simulation.
  static void Function(Map<String, dynamic> state, double dt)? simulationStepFor(
    String templateFamily,
  ) {
    switch (templateFamily) {
      case 'unit-circle':
        return UnitCircleRenderer.simulationStep;
      case 'projectile':
        return ProjectileRenderer.simulationStep;
      default:
        return null;
    }
  }

  /// Returns the 'play' handler for a template (e.g., projectile launch)
  static void Function(Map<String, dynamic> state)? playHandlerFor(
      String templateFamily) {
    switch (templateFamily) {
      case 'projectile':
        return ProjectileRenderer.launch;
      default:
        return null;
    }
  }
}

