class _ViewerInteractiveVisualCardState
    extends State<_ViewerInteractiveVisualCard>
    with TickerProviderStateMixin {
  late Map<String, dynamic> _state;
  int _stepIndex = 0;
  RuntimeController? _controller;

  @override
  void initState() {
    super.initState();
    final initial = widget.spec['initialState'];
    _state = initial is Map ? Map<String, dynamic>.from(initial) : {};

    // Set up RuntimeController
    final template = widget.spec['template'] as String? ?? 'generic';
    final runtimeSpec = widget.spec['runtime'];
    final runtimeMode = runtimeSpec is Map
        ? (runtimeSpec['mode'] as String? ?? 'static')
        : 'static';
    final autoplay = runtimeSpec is Map
        ? (runtimeSpec['autoplay'] as bool? ?? false)
        : false;

    _controller = RuntimeController(
      mode: runtimeMode,
      initialState: Map<String, dynamic>.from(_state),
    );
    _controller!.simulationStep = VisualRendererFactory.simulationStepFor(template);
    _controller!.attach(this);
    if (autoplay) {
      _controller!.play();
    }
  }

  @override
  void dispose() {
    _controller?.dispose();
    super.dispose();
  }

  void _handleAction(String action) {
    final template = widget.spec['template'] as String? ?? 'generic';
    if (action == 'reset') {
      final initial = widget.spec['initialState'];
      _controller?.reset();
      setState(() {
        _state = initial is Map ? Map<String, dynamic>.from(initial) : {};
        _stepIndex = 0;
      });
    } else if (action == 'step') {
      _doStep();
    } else if (action == 'randomize') {
      _doRandomize();
    } else if (action == 'play') {
      final playHandler = VisualRendererFactory.playHandlerFor(template);
      if (playHandler != null) {
        // For projectile: launch then play simulation
        _controller?.step(playHandler);
        _controller?.play();
      } else {
        _controller?.play();
      }
    } else if (action == 'pause') {
      _controller?.pause();
    }
  }

