/// Runtime configuration for scene-v1 blocks
class VisualRuntime {
  static const String modeStatic = 'static';
  static const String modeParametric = 'parametric';
  static const String modeSimulation = 'simulation';
  static const Set<String> allModes = {modeStatic, modeParametric, modeSimulation};

  final String mode; // 'static' | 'parametric' | 'simulation'
  final double timeScale;
  final String solver; // 'euler' | 'rk4'
  final bool autoplay;

  const VisualRuntime({
    this.mode = modeStatic,
    this.timeScale = 1.0,
    this.solver = 'euler',
    this.autoplay = false,
  });

  factory VisualRuntime.fromJson(Map<String, dynamic> json) {
    final rawMode = json['mode'] as String? ?? modeStatic;
    return VisualRuntime(
      mode: allModes.contains(rawMode) ? rawMode : modeStatic,
      timeScale: (json['timeScale'] as num?)?.toDouble() ?? 1.0,
      solver: json['solver'] as String? ?? 'euler',
      autoplay: json['autoplay'] as bool? ?? false,
    );
  }

  Map<String, dynamic> toJson() => {
    'mode': mode,
    'timeScale': timeScale,
    'solver': solver,
    'autoplay': autoplay,
  };

  VisualRuntime copyWith({
    String? mode,
    double? timeScale,
    String? solver,
    bool? autoplay,
  }) => VisualRuntime(
    mode: mode ?? this.mode,
    timeScale: timeScale ?? this.timeScale,
    solver: solver ?? this.solver,
    autoplay: autoplay ?? this.autoplay,
  );
}

