### 3.2 `runtime_controller.dart`

```dart
import 'package:flutter/material.dart';
import 'package:flutter/scheduler.dart';

enum RuntimeLifecycle { idle, ready, running, paused, disposed }

/// Controls the lifecycle and state of an interactive visual scene.
/// Handles static (step-driven), parametric (param-reactive), and
/// simulation (Ticker-based) runtime modes.
class RuntimeController extends ChangeNotifier {
  final String mode; // 'static' | 'parametric' | 'simulation'
  final Map<String, dynamic> initialState;

  Map<String, dynamic> _state;
  RuntimeLifecycle _lifecycle = RuntimeLifecycle.idle;
  Ticker? _ticker;
  Duration _lastTick = Duration.zero;
  bool _tickerAttached = false;

  /// Called each simulation tick with current state and delta time (seconds).
  void Function(Map<String, dynamic> state, double dt)? simulationStep;

  RuntimeController({
    required this.mode,
    required this.initialState,
  }) : _state = Map<String, dynamic>.from(initialState);

  Map<String, dynamic> get state => Map<String, dynamic>.from(_state);
  RuntimeLifecycle get lifecycle => _lifecycle;
  bool get isRunning => _lifecycle == RuntimeLifecycle.running;
  bool get isPaused => _lifecycle == RuntimeLifecycle.paused;
  bool get isReady => _lifecycle == RuntimeLifecycle.ready;

  void attach(TickerProvider vsync) {
    if (_tickerAttached || _lifecycle == RuntimeLifecycle.disposed) return;
    if (mode == 'simulation') {
      _ticker = vsync.createTicker(_onTick);
      _tickerAttached = true;
    }
    _lifecycle = RuntimeLifecycle.ready;
    notifyListeners();
  }

  void ready() {
    if (_lifecycle == RuntimeLifecycle.idle) {
      _lifecycle = RuntimeLifecycle.ready;
      notifyListeners();
    }
  }

  void play() {
    if (_lifecycle == RuntimeLifecycle.disposed) return;
    if (mode == 'simulation' && _ticker != null && !_ticker!.isActive) {
      _lastTick = Duration.zero;
      _ticker!.start();
    }
    _lifecycle = RuntimeLifecycle.running;
    notifyListeners();
  }

  void pause() {
    if (_lifecycle != RuntimeLifecycle.running) return;
    if (mode == 'simulation') _ticker?.stop();
    _lifecycle = RuntimeLifecycle.paused;
    notifyListeners();
  }

  void reset() {
    if (_lifecycle == RuntimeLifecycle.disposed) return;
    if (mode == 'simulation') {
      _ticker?.stop();
      _lastTick = Duration.zero;
    }
    _state = Map<String, dynamic>.from(initialState);
    _lifecycle = RuntimeLifecycle.ready;
    notifyListeners();
  }

  /// Step forward (for static mode)
  void step(void Function(Map<String, dynamic>) stepFn) {
    if (_lifecycle == RuntimeLifecycle.disposed) return;
    stepFn(_state);
    notifyListeners();
  }

  /// Update a parameter value (for parametric/slider controls)
  void updateParam(String key, dynamic value) {
    if (_lifecycle == RuntimeLifecycle.disposed) return;
    _state[key] = value;
    notifyListeners();
  }

  void _onTick(Duration elapsed) {
    if (_lifecycle != RuntimeLifecycle.running) return;
    if (_lastTick == Duration.zero) {
      _lastTick = elapsed;
      return;
    }
    final dt = (elapsed - _lastTick).inMicroseconds / 1000000.0;
    _lastTick = elapsed;
    if (dt <= 0 || dt > 0.1) return; // skip bad frames
    simulationStep?.call(_state, dt);
    notifyListeners();
  }

  @override
  void dispose() {
    _lifecycle = RuntimeLifecycle.disposed;
    _ticker?.stop();
    _ticker?.dispose();
    _ticker = null;
    super.dispose();
  }
}
