import 'dart:math' as math;
import 'package:flutter/material.dart';
import '../visual_template_renderer.dart';

class ProjectileRenderer extends VisualTemplateRenderer {
  const ProjectileRenderer({
    required super.state,
    required super.scene,
    required super.isDark,
    super.repaint,
  });

  /// Euler integration step for projectile motion
  static void simulationStep(Map<String, dynamic> state, double dt) {
    final double x = (state['_x'] as num?)?.toDouble() ?? 0.0;
    final double y = (state['_y'] as num?)?.toDouble() ?? 0.0;
    double vx = (state['_vx'] as num?)?.toDouble() ?? 0.0;
    double vy = (state['_vy'] as num?)?.toDouble() ?? 0.0;
    final double g = (state['gravity'] as num?)?.toDouble() ?? 9.8;

    if (y <= 0 && (state['_launched'] as bool? ?? false) && vy < 0) {
      // Hit the ground
      state['_launched'] = false;
      return;
    }

    vy -= g * dt;
    final nx = x + vx * dt;
    final ny = y + vy * dt;

    final trail = List<Map<String, double>>.from(
      (state['_trail'] as List?)?.map((e) => Map<String, double>.from(e as Map)) ?? [],
    );
    if (state['_launched'] as bool? ?? false) {
      trail.add({'x': x, 'y': y});
      if (trail.length > 200) trail.removeAt(0);
    }

    state['_x'] = nx;
    state['_y'] = ny < 0 ? 0.0 : ny;
    state['_vx'] = vx;
    state['_vy'] = ny < 0 ? 0.0 : vy;
    state['_trail'] = trail;
  }

  /// Launch the projectile based on angle and velocity
  static void launch(Map<String, dynamic> state) {
    final angle = (state['angle'] as num?)?.toDouble() ?? 45.0;
    final v0 = (state['velocity'] as num?)?.toDouble() ?? 20.0;
    final rad = angle * math.pi / 180;
    state['_x'] = 0.0;
    state['_y'] = 0.0;
    state['_vx'] = v0 * math.cos(rad);
    state['_vy'] = v0 * math.sin(rad);
    state['_trail'] = <Map<String, double>>[];
    state['_launched'] = true;
  }

  @override
  void paint(Canvas canvas, Size size) {
    final angle = (state['angle'] as num?)?.toDouble() ?? 45.0;
    final v0 = (state['velocity'] as num?)?.toDouble() ?? 20.0;
    final g = (state['gravity'] as num?)?.toDouble() ?? 9.8;
    final launched = state['_launched'] as bool? ?? false;

    // Calculate trajectory range for scaling
    final rad = angle * math.pi / 180;
    final totalTime = 2 * v0 * math.sin(rad) / g;
    final maxRange = v0 * math.cos(rad) * totalTime;
    final maxHeight = math.pow(v0 * math.sin(rad), 2) / (2 * g);
    final scaleX = maxRange > 0 ? (size.width * 0.9) / maxRange : 1.0;
    final scaleY = maxHeight > 0 ? (size.height * 0.8) / maxHeight : 1.0;

    double toCanvasX(double wx) => size.width * 0.05 + wx * scaleX;
    double toCanvasY(double wy) => size.height * 0.9 - wy * scaleY;

    // Draw ground
    canvas.drawLine(
      Offset(0, toCanvasY(0)),
      Offset(size.width, toCanvasY(0)),
      Paint()..color = axisColor..strokeWidth = 1.5,
    );

    // Draw predicted trajectory (dashed)
    if (!launched) {
      final dashPaint = Paint()
        ..color = axisColor.withOpacity(0.5)
        ..strokeWidth = 1.0
        ..style = PaintingStyle.stroke;
      final path = Path();
      bool first = true;
      for (int i = 0; i <= 100; i++) {
        final t = (i / 100) * totalTime;
        final wx = v0 * math.cos(rad) * t;
        final wy = v0 * math.sin(rad) * t - 0.5 * g * t * t;
        if (wy < 0) break;
        final cx = toCanvasX(wx);
        final cy = toCanvasY(wy);
        if (first) { path.moveTo(cx, cy); first = false; }
        else path.lineTo(cx, cy);
      }
      canvas.drawPath(path, dashPaint);
    }

    // Draw trail
    final trail = (state['_trail'] as List?)
        ?.map((e) => Map<String, double>.from(e as Map))
        .toList() ?? [];
    if (trail.length > 1) {
      final trailPaint = Paint()
        ..color = primaryColor.withOpacity(0.5)
        ..strokeWidth = 2.0
        ..style = PaintingStyle.stroke;
      final path = Path();
      path.moveTo(toCanvasX(trail.first['x']!), toCanvasY(trail.first['y']!));
      for (final pt in trail.skip(1)) {
        path.lineTo(toCanvasX(pt['x']!), toCanvasY(pt['y']!));
      }
      canvas.drawPath(path, trailPaint);
    }

    // Draw current ball
    final curX = (state['_x'] as num?)?.toDouble() ?? 0.0;
    final curY = (state['_y'] as num?)?.toDouble() ?? 0.0;
    canvas.drawCircle(
      Offset(toCanvasX(curX), toCanvasY(curY)),
      6,
      Paint()..color = accentColor,
    );

    // Info label
    final infoText = launched
        ? 'x=${curX.toStringAsFixed(1)}m  y=${curY.toStringAsFixed(1)}m'
        : '${angle.toStringAsFixed(0)}° @ ${v0.toStringAsFixed(0)} m/s';
    final tp = TextPainter(
      text: TextSpan(text: infoText, style: TextStyle(color: labelColor, fontSize: 10)),
      textDirection: TextDirection.ltr,
    )..layout();
    tp.paint(canvas, Offset(8, 8));
  }

  @override
  bool shouldRepaint(ProjectileRenderer old) =>
      old.state['_x'] != state['_x'] ||
      old.state['_y'] != state['_y'] ||
      old.state['angle'] != state['angle'] ||
      old.state['velocity'] != state['velocity'] ||
      old.state['_launched'] != state['_launched'];
}
```

### 3.5 `visual_renderer_factory.dart`

```dart
import 'package:flutter/material.dart';
import 'visual_template_renderer.dart';
import 'renderers/sorting_bars_renderer.dart';
import 'renderers/function_plot_renderer.dart';
import 'renderers/unit_circle_renderer.dart';
import 'renderers/ideal_gas_piston_renderer.dart';
import 'renderers/projectile_renderer.dart';

class VisualRendererFactory {
  VisualRendererFactory._();

  static CustomPainter? create({
    required String templateFamily,
    required Map<String, dynamic> state,
    required Map<String, dynamic> scene,
    required bool isDark,
    Listenable? repaint,
  }) {
    switch (templateFamily) {
      case 'sorting-bars':
        return SortingBarsRenderer(state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'function-plot':
        return FunctionPlotRenderer(state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'unit-circle':
        return UnitCircleRenderer(state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'ideal-gas-piston':
        return IdealGasPistonRenderer(state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'projectile':
        return ProjectileRenderer(state: state, scene: scene, isDark: isDark, repaint: repaint);
      default:
        return null;
    }
  }

  /// Returns the simulation step function for a template, or null if not a simulation.
  static void Function(Map<String, dynamic> state, double dt)? simulationStepFor(
    String templateFamily,
  ) {
    switch (templateFamily) {
      case 'unit-circle':
        return UnitCircleRenderer.simulationStep;
      case 'projectile':
        return ProjectileRenderer.simulationStep;
      default:
        return null;
    }
  }

  /// Returns the 'play' handler for a template (e.g., projectile launch)
  static void Function(Map<String, dynamic> state)? playHandlerFor(String templateFamily) {
    switch (templateFamily) {
      case 'projectile':
        return ProjectileRenderer.launch;
      default:
        return null;
    }
  }
}
```

### 3.6 Refactor `_ViewerInteractiveVisualCard` in `Viewer/lib/screens/lesson_screen.dart`

Keep the existing `_ViewerInteractiveVisualCard` widget but update `_ViewerInteractiveVisualCardState` to:

1. Add `with TickerProviderStateMixin`
2. Add `RuntimeController? _controller` field
3. In `initState`: 
   - Parse the spec to get `template`, `runtime.mode`, `initialState`, etc.
   - Create `RuntimeController(mode: runtimeMode, initialState: initialStateMap)`
   - Set `_controller.simulationStep = VisualRendererFactory.simulationStepFor(template)`
   - Call `_controller.attach(this)` 
   - If `autoplay`: call `_controller.play()`
4. In `dispose`: call `_controller?.dispose()` then `super.dispose()`
5. `_handleAction`: delegate to controller — `reset` → `_controller.reset()`, `play` → `_controller.play()`, `pause` → `_controller.pause()`, `step` → `_controller.step((s) => SortingBarsRenderer.performStep(s))` for sorting-bars, etc.
6. `_buildScene`: use `VisualRendererFactory.create(...)` for templates with renderers; keep fallback for `variable-binding-memory` (no renderer yet) and `generic`
7. Replace the `setState(() => _state[key] = v)` slider update with `_controller?.updateParam(key, v)`
8. Wrap the CustomPaint with `ListenableBuilder(listenable: _controller!, ...)`

Keep `_stepVariableMemory` and the `variable-binding-memory` rendering inline (no renderer for this yet).
Keep `_doRandomize` for sorting-bars.

Remove `_ViewerSortingBarsPainter` class (it's now in `SortingBarsRenderer`), use `SortingBarsRenderer` instead.

Add these imports at the top of lesson_screen.dart:
```dart
import '../widgets/interactive_visual/runtime_controller.dart';
import '../widgets/interactive_visual/visual_renderer_factory.dart';
import '../widgets/interactive_visual/renderers/sorting_bars_renderer.dart';
```

The key change is that `_state` is now managed by `_controller.state` (a copy), and mutations go through `_controller.updateParam` / `_controller.step` / `_controller.reset` etc.

For `_buildScene`, when `VisualRendererFactory.create(...)` returns non-null:
```dart
return Container(
  color: bg,
  child: ListenableBuilder(
    listenable: _controller!,
    builder: (context, _) {
      final painter = VisualRendererFactory.create(
        templateFamily: template,
        state: _controller!.state,
        scene: Map<String, dynamic>.from(widget.spec['scene'] as Map? ?? {}),
        isDark: isDark,
      );
      if (painter == null) return _buildFallbackScene(template, isDark, bg);
      return CustomPaint(painter: painter, size: Size.infinite);
    },
  ),
);
```

When `VisualRendererFactory.create(...)` returns null (generic, variable-binding-memory), keep the existing inline rendering, but read state from `_controller?.state ?? _state`.

### 3.7 Viewer tests `Viewer/test/interactive_visual_runtime_test.dart`

```dart
import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:viewer/widgets/interactive_visual/runtime_controller.dart';
import 'package:viewer/widgets/interactive_visual/renderers/sorting_bars_renderer.dart';
import 'package:viewer/widgets/interactive_visual/renderers/unit_circle_renderer.dart';
import 'package:viewer/widgets/interactive_visual/renderers/function_plot_renderer.dart';

void main() {
  group('RuntimeController lifecycle', () {
    test('starts in idle state', () {
      final controller = RuntimeController(
        mode: 'static',
        initialState: {'x': 1},
      );
      expect(controller.lifecycle, RuntimeLifecycle.idle);
      controller.dispose();
    });

    test('ready() transitions from idle to ready', () {
      final controller = RuntimeController(
        mode: 'static',
        initialState: {},
      );
      controller.ready();
      expect(controller.lifecycle, RuntimeLifecycle.ready);
      controller.dispose();
    });

    test('reset restores initial state', () {
      final controller = RuntimeController(
        mode: 'static',
        initialState: {'count': 0},
      );
      controller.ready();
      controller.updateParam('count', 5);
      expect(controller.state['count'], 5);
      controller.reset();
      expect(controller.state['count'], 0);
      controller.dispose();
    });

    test('updateParam triggers notifyListeners', () {
      final controller = RuntimeController(
        mode: 'parametric',
        initialState: {'a': 1.0},
      );
      controller.ready();
      int notifyCount = 0;
      controller.addListener(() => notifyCount++);
      controller.updateParam('a', 2.0);
      expect(notifyCount, 1);
      expect(controller.state['a'], 2.0);
      controller.dispose();
    });

    test('dispose transitions to disposed lifecycle', () {
      final controller = RuntimeController(
        mode: 'static',
        initialState: {},
      );
      controller.dispose();
      expect(controller.lifecycle, RuntimeLifecycle.disposed);
    });

    test('updateParam is no-op after dispose', () {
      final controller = RuntimeController(
        mode: 'parametric',
        initialState: {'x': 1},
      );
      controller.dispose();
      // Should not throw
      controller.updateParam('x', 99);
      // State should not change (though it's disposed)
    });
  });

  group('SortingBarsRenderer step logic', () {
    test('performStep advances bubble sort', () {
      final state = {
        'values': [3, 1, 2],
        'stepIndex': 0,
        'comparing': <int>[],
        'swapped': <int>[],
        'sorted': <int>[],
      };
      SortingBarsRenderer.performStep(state);
      // After first step: should compare [0, 1] and swap 3 and 1
      expect(state['comparing'], [0, 1]);
      expect(state['stepIndex'], 1);
      final vals = state['values'] as List<int>;
      expect(vals[0], 1); // 3 and 1 were swapped
      expect(vals[1], 3);
    });

    test('performStep marks all sorted when done', () {
      // Already sorted array with stepIndex past all comparisons
      final n = 3;
      final state = {
        'values': [1, 2, 3],
        'stepIndex': (n - 1) * (n - 1), // past the last pass
        'comparing': <int>[],
        'swapped': <int>[],
        'sorted': <int>[],
      };
      SortingBarsRenderer.performStep(state);
      final sorted = state['sorted'] as List<int>;
      expect(sorted.length, n);
    });
  });

  group('UnitCircleRenderer simulation step', () {
    test('angle increases over time', () {
      final state = {'angle': 0.0};
      UnitCircleRenderer.simulationStep(state, 1.0 / 60);
      final angle = (state['angle'] as num).toDouble();
      expect(angle, greaterThan(0));
      expect(angle, lessThan(360));
    });

    test('angle wraps around 360', () {
      final state = {'angle': 359.5};
      UnitCircleRenderer.simulationStep(state, 1.0 / 60);
      final angle = (state['angle'] as num).toDouble();
      expect(angle, lessThan(360));
      expect(angle, greaterThanOrEqualTo(0));
    });
  });

  group('FunctionPlotRenderer', () {
    test('shouldRepaint returns true when a changes', () {
      final r1 = FunctionPlotRenderer(
        state: {'a': 1.0, 'b': 0.0, 'c': 0.0},
        scene: {},
        isDark: false,
      );
      final r2 = FunctionPlotRenderer(
        state: {'a': 2.0, 'b': 0.0, 'c': 0.0},
        scene: {},
        isDark: false,
      );
      expect(r1.shouldRepaint(r2), isTrue);
    });

    test('shouldRepaint returns false when state unchanged', () {
      const stateMap = {'a': 1.0, 'b': 0.0, 'c': 0.0};
      final r1 = FunctionPlotRenderer(state: stateMap, scene: {}, isDark: false);
      final r2 = FunctionPlotRenderer(state: stateMap, scene: {}, isDark: false);
      expect(r1.shouldRepaint(r2), isFalse);
    });
  });
}
```

