/// Pill-shaped button
class _PillButton extends StatelessWidget {
  final String label;
  final bool filled;
  final IconData? icon;
  final VoidCallback onTap;
  final bool prominent;

  const _PillButton({
    required this.label,
    required this.filled,
    this.icon,
    required this.onTap,
    this.prominent = false,
  });

  @override
  Widget build(BuildContext context) {
    if (filled) {
      return ElevatedButton.icon(
        onPressed: onTap,
        style: ElevatedButton.styleFrom(
          backgroundColor: const Color(0xFF58CC02),
          foregroundColor: const Color(0xFF123300),
          elevation: 6,
          shadowColor: const Color(0x333A7A00),
          padding: EdgeInsets.symmetric(
            horizontal: prominent ? 24 : 18,
            vertical: prominent ? 18 : 14,
          ),
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(999),
          ),
          textStyle: TextStyle(
            fontWeight: prominent ? FontWeight.w900 : FontWeight.w800,
            fontSize: prominent ? 17 : 15,
          ),
        ),
        icon: Icon(
          icon ?? Icons.arrow_forward_rounded,
          size: prominent ? 26 : 18,
        ),
        label: Text(label),
      );
    }

    return OutlinedButton.icon(
      onPressed: onTap,
      style: OutlinedButton.styleFrom(
        foregroundColor: _C.text,
        backgroundColor: Colors.white.withValues(alpha: 0.65),
        side: const BorderSide(color: Color(0x33506E96)),
        padding: const EdgeInsets.symmetric(horizontal: 18, vertical: 14),
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(999)),
        textStyle: const TextStyle(fontWeight: FontWeight.w700, fontSize: 15),
      ),
      icon: Icon(icon ?? Icons.arrow_outward_rounded, size: 18),
      label: Text(label),
    );
  }
}

