/// Pill-shaped button with 3D raised effect for filled variant
class _PillButton extends StatefulWidget {
  final String label;
  final bool filled;
  final IconData? icon;
  final VoidCallback onTap;
  final bool prominent;

  const _PillButton({
    required this.label,
    required this.filled,
    this.icon,
    required this.onTap,
    this.prominent = false,
  });

  @override
  State<_PillButton> createState() => _PillButtonState();
}

class _PillButtonState extends State<_PillButton> {
  bool _pressed = false;

  @override
  Widget build(BuildContext context) {
    if (widget.filled) {
      const baseColor = Color(0xFF58CC02);
      const depthColor = Color(0xFF3D9600); // darker green = 3D bottom face
      const textColor = Color(0xFF123300);
      final depthHeight = _pressed ? 0.0 : 4.0;
      final hPad = widget.prominent ? 24.0 : 18.0;
      final vPad = widget.prominent ? 18.0 : 14.0;

      return GestureDetector(
        onTapDown: (_) => setState(() => _pressed = true),
        onTapUp: (_) {
          setState(() => _pressed = false);
          widget.onTap();
        },
        onTapCancel: () => setState(() => _pressed = false),
        child: AnimatedContainer(
          duration: const Duration(milliseconds: 80),
          curve: Curves.easeOut,
          decoration: BoxDecoration(
            color: depthColor,
            borderRadius: BorderRadius.circular(999),
          ),
          // Bottom padding creates the visible 3D depth face
          padding: EdgeInsets.only(bottom: depthHeight),
          child: AnimatedContainer(
            duration: const Duration(milliseconds: 80),
            curve: Curves.easeOut,
            // Slide down on press, closing the gap
            transform: Matrix4.translationValues(0, _pressed ? depthHeight : 0, 0),
            decoration: BoxDecoration(
              color: baseColor,
              borderRadius: BorderRadius.circular(999),
              boxShadow: _pressed
                  ? null
                  : [
                      BoxShadow(
                        color: const Color(0x553D9600),
                        blurRadius: 8,
                        offset: const Offset(0, 4),
                      ),
                    ],
            ),
            padding: EdgeInsets.symmetric(horizontal: hPad, vertical: vPad),
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                Icon(
                  widget.icon ?? Icons.arrow_forward_rounded,
                  size: widget.prominent ? 22 : 18,
                  color: textColor,
                ),
                const SizedBox(width: 8),
                Text(
                  widget.label,
                  style: TextStyle(
                    fontWeight:
                        widget.prominent ? FontWeight.w900 : FontWeight.w800,
                    fontSize: widget.prominent ? 17 : 15,
                    color: textColor,
                  ),
                ),
              ],
            ),
          ),
        ),
      );
    }

    return OutlinedButton.icon(
      onPressed: widget.onTap,
      style: OutlinedButton.styleFrom(
        foregroundColor: _C.text,
        backgroundColor: Colors.white.withValues(alpha: 0.65),
        side: const BorderSide(color: Color(0x33506E96)),
        padding: const EdgeInsets.symmetric(horizontal: 18, vertical: 14),
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(999)),
        textStyle: const TextStyle(fontWeight: FontWeight.w700, fontSize: 15),
      ),
      icon: Icon(widget.icon ?? Icons.arrow_outward_rounded, size: 18),
      label: Text(widget.label),
    );
  }
}

