                                : const SizedBox.shrink(),
                          ),
                        ],
                      ),
                    ],
                  ],
                ),
              ),
              const SizedBox(height: 30),
              SizedBox(
                width: heroPillWidth,
                height: heroPillHeight,
                child: _PillButton(
                  label: t.isZh
                      ? t.landingStartCreating
